      orderDateVisible: true,
      freightVisible: true,
      shipCountryVisible: true,
      shipNameVisible: false,
      salaryVisible: false,
      costVisible: false,
      isActiveVisible: false,
      shipCityVisible: false,
      commandActionsVisible: false,
      shipNameWidth: '130',
